"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["27906"],{58690(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_derivacao_fato.fato_desconhecido","status":422,"titulo":"O fato derivado n\xe3o pertence ao vocabul\xe1rio de fatos do candidato"},"descricao":{"codigo":"uniplus.selecao.configuracao_derivacao_fato.fato_desconhecido","requisitos":[],"oQueAconteceu":["Na defini\xe7\xe3o das regras de deriva\xe7\xe3o do processo, o `codigoFato` de uma configura\xe7\xe3o tem forma\\nv\xe1lida, mas n\xe3o corresponde a nenhum fato do cat\xe1logo de fatos do candidato. A confer\xeancia\\ncompara o c\xf3digo exatamente como foi enviado.","Esta recusa vem da etapa que confere o pedido contra o cat\xe1logo, que s\xf3 roda depois de a forma\\nde todas as configura\xe7\xf5es ser aceita (ver\\n[`codigo_fato_obrigatorio`](/erros/uniplus.selecao.configuracao_derivacao_fato.codigo_fato_obrigatorio)).\\nNessa etapa o processamento para na primeira configura\xe7\xe3o ou regra que falhar: corrigir esta\\nconfigura\xe7\xe3o pode revelar, no reenvio, uma recusa de outra configura\xe7\xe3o da mesma lista.","Fato que existe no cat\xe1logo mas n\xe3o pode ter regras de deriva\xe7\xe3o \xe9 recusado em\\n[`fato_nao_derivavel`](/erros/uniplus.selecao.configuracao_derivacao_fato.fato_nao_derivavel)."],"comoResolver":["Confira o c\xf3digo no cat\xe1logo de fatos do candidato e informe, em `codigoFato`, o c\xf3digo de um\\nfato derivado por regra de deriva\xe7\xe3o, exatamente como est\xe1 no cat\xe1logo. Se o fato ainda n\xe3o\\nexiste, ele precisa ser cadastrado no cat\xe1logo antes de receber regras no processo."],"ondeAparece":["Defini\xe7\xe3o de regras de deriva\xe7\xe3o de fatos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao derivacao fato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);